  border-radius: var(--radius-sm);
  background: var(--color-surface-muted);
}

.btn {
  min-height: var(--control-height);
  min-width: var(--control-min-target);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 var(--space-4);
