.slot:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.result-panel {
  padding: var(--space-3);
  border-radius: var(--radius-sm);
  background: var(--color-success-bg);
  color: var(--color-success);
}

.data-list {
  margin: 0;
  padding: 0;
  list-style: none;
  gap: 0;
}

.data-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--color-border);
  overflow-wrap: anywhere;
}

.data-row:last-child {
  border-bottom: 0;
}

.data-head {
  display: none;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-muted);
}

.cell-strong {
  font-weight: var(--font-weight-bold);
}

.chart-details summary {
  min-height: var(--control-min-target);
  display: flex;
  align-items: center;
  cursor: pointer;
}

.chart-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-size-sm);
}

.chart-table th,
.chart-table td {
  padding: var(--space-2);
  text-align: left;
  border-bottom: 1px solid var(--color-border);
}

.chart-details {
  overflow-x: auto;
}

.chart {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.branch-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding-bottom: var(--space-3);
}

.branch-group-title {
  font-size: var(--font-size-md);
}

.bar-row {
  display: grid;
  grid-template-columns: minmax(84px, 110px) minmax(0, 1fr) 32px;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-sm);
}

.bar-track {
  height: 16px;
  border-radius: var(--radius-sm);
  background: var(--color-surface-muted);
  overflow: hidden;
}

.bar-fill {
  display: block;
  height: 100%;
  min-width: 2px;
}

.bar-value {
  font-weight: var(--font-weight-bold);
}

.bar-waiting { background: var(--color-status-waiting); }
.bar-called { background: var(--color-status-called); }
.bar-serving { background: var(--color-status-serving); }
.bar-completed { background: var(--color-status-completed); }
.bar-cancelled { background: var(--color-status-cancelled); }
.bar-no-show { background: var(--color-status-no-show); }

@media (min-width: 481px) {
  .slot-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 768px) {
  .card {
    padding: var(--space-5);
  }

  .data-list {
    padding: var(--space-3) var(--space-5);
  }

  .data-row {
    display: grid;
    align-items: center;
    column-gap: var(--space-3);
  }

  .data-head {
    display: grid;
  }

  .history-row { grid-template-columns: 1.1fr 1fr 1.2fr 1.4fr 1fr; }
  .monitor-row { grid-template-columns: 1.1fr 1.1fr 1.3fr 1.1fr 1fr 0.8fr 1fr 0.7fr; }
  .branch-admin-row { grid-template-columns: 1.3fr 0.5fr 1.5fr 0.9fr 0.6fr 1.5fr 1.2fr 0.8fr 0.6fr; }
  .service-admin-row { grid-template-columns: 1.3fr 0.5fr 2fr 0.8fr 1fr 0.8fr 1.6fr; }
  .staff-admin-row { grid-template-columns: 1.2fr 1.8fr 1.2fr 1fr 0.6fr; }
}

.book-layout {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.book-form-column {
  min-width: 0;
}

.branch-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.branch-card {
  cursor: pointer;
}

.branch-card-selected {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px var(--color-primary);
}

.waiting-count {
  font-weight: var(--font-weight-medium);
}

.booking-card {
  max-width: var(--width-form);
}

.ticket-result {
  align-items: flex-start;
}

.grid-2,
.grid-3,
.grid-4,
.grid-stats {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: minmax(0, 1fr);
}

.grid-4,
.grid-stats {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ticket-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.ticket-card-called {
  border-left: 6px solid var(--color-status-called);
}

.ticket-card-serving {
  border-left: 6px solid var(--color-status-serving);
}

.ticket-metric {
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-medium);
}

.ticket-message {
  font-weight: var(--font-weight-bold);
  color: var(--color-status-called);
}

.appointment-when {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-bold);
}

.strip {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
}

.desk-layout {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: minmax(0, 1fr);
}

.current-ticket {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-2);
}

.action-buttons {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1fr);
}

.waiting-list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.waiting-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--color-border);
}

.waiting-customer {
  flex: 1 1 100px;
  min-width: 0;
  overflow-wrap: anywhere;
}

.grid-stats .stat-value {
  font-size: var(--font-size-xl);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-4);
}

.toolbar .field {
  min-width: 200px;
}

.clock-controls {
  max-width: 100%;
}

.display-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  padding: var(--space-4);
  background: var(--color-nav-bg);
  color: var(--color-nav-text);
}

.display-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
}

.display-header h1 {
  font-size: var(--font-size-2xl);
}

.display-clock {
  font-family: var(--font-mono);
  font-size: var(--font-size-lg);
}

.display-page .card {
  background: transparent;
  color: var(--color-nav-text);
}

.display-select {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  max-width: var(--width-form);
}

.display-grid {
  display: grid;
  gap: var(--space-5);
  grid-template-columns: minmax(0, 1fr);
}

.display-heading {
  margin-bottom: var(--space-3);
  font-size: var(--font-size-xl);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.display-tiles {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
}

.display-tile {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
  border: 2px solid var(--color-nav-text);
  border-radius: var(--radius-md);
}

.display-number {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-bold);
  font-size: var(--font-size-display);
  line-height: var(--line-height-tight);
  overflow-wrap: anywhere;
}

.display-counter {
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
}

.display-status,
.display-empty {
  font-size: var(--font-size-lg);
}

.display-next-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.display-next-item {
  padding-bottom: var(--space-2);
  border-bottom: 1px solid rgba(232, 238, 246, 0.35);
  font-family: var(--font-mono);
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
}

@media (min-width: 768px) {
  .grid-2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid-3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid-4 {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .desk-layout {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .display-page {
    padding: var(--space-6);
  }
}

@media (min-width: 1024px) {
  .book-layout {
    flex-direction: row;
    align-items: flex-start;
  }

  .book-form-column {
    order: 2;
    width: var(--width-form);
    flex-shrink: 0;
  }

  .branch-list {
    order: 1;
    flex: 1;
    min-width: 0;
  }

  .grid-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .grid-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .display-grid {
    grid-template-columns: 2fr 1fr;
  }
}

tool_input.command:
sed -i '249,254c\.stat-value {
  font-size: clamp(1.125rem, 5vw, var(--font-size-2xl));
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  white-space: nowrap;
}' src/styles/components.css

sed -i '68,71c\.ticket-metric {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
}' src/styles/pages.css
